#!/bin/bash
# Uninstall script for SuperDuper!
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling SuperDuper!..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping SuperDuper! if running..."
pkill -f "SuperDuper!" 2>/dev/null || true

# Unload service com.shirtpocket.SuperDuper4.menu
echo "Unloading service com.shirtpocket.SuperDuper4.menu..."
launchctl unload -w /Library/LaunchAgents/com.shirtpocket.SuperDuper4.menu.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.shirtpocket.SuperDuper4.menu.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.shirtpocket.SuperDuper4.menu.plist 2>/dev/null || true

# Remove /Applications/SuperDuper!.app
echo "Removing /Applications/SuperDuper!.app..."
if [ -d "/Applications/SuperDuper!.app" ]; then
    rm -rf "/Applications/SuperDuper!.app" 2>/dev/null || true
elif [ -f "/Applications/SuperDuper!.app" ]; then
    rm -f "/Applications/SuperDuper!.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/CrashReporter/SuperDuper!_*.plist
echo "Removing $HOME/Library/Application Support/CrashReporter/SuperDuper!_*.plist..."
if [ -d "$HOME/Library/Application Support/CrashReporter/SuperDuper!_*.plist" ]; then
    rm -rf "$HOME/Library/Application Support/CrashReporter/SuperDuper!_*.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/CrashReporter/SuperDuper!_*.plist" ]; then
    rm -f "$HOME/Library/Application Support/CrashReporter/SuperDuper!_*.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/SuperDuper!
