    rm -rf "$HOME/Library/Application Support/SuperDuper!" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/SuperDuper!" ]; then
    rm -f "$HOME/Library/Application Support/SuperDuper!" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/com.shirtpocket.SuperDuper4
echo "Removing $HOME/Library/Caches/com.shirtpocket.SuperDuper4..."
if [ -d "$HOME/Library/Caches/com.shirtpocket.SuperDuper4" ]; then
    rm -rf "$HOME/Library/Caches/com.shirtpocket.SuperDuper4" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/com.shirtpocket.SuperDuper4" ]; then
